import asyncio, os
from playwright.async_api import async_playwright
B = os.path.dirname(os.path.abspath(__file__)); SH = B + "/ptshots"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await (await b.new_context(viewport={"width": 1480, "height": 1200})).new_page(); errs = []
        pg.on("pageerror", lambda e: errs.append("PAGEERR " + str(e)))
        await pg.goto("file://" + B + "/mg2_mock.html"); await pg.wait_for_timeout(500)
        ev = lambda js: pg.evaluate(js)
        T = lambda: ev("(document.querySelector('.toast-fm')||{}).textContent||''")
        U = lambda k: ev(f"JSON.stringify(__mg.U().{k})")
        await pg.click('.mg-tile[data-k="eff"]'); print("tile→", await U("view"), await U("sel"))
        await pg.click('.mg-br >> nth=0'); print("bf:", await U("bf"), "| chip:", await ev("(document.querySelector('.mg-fchip')||{}).textContent"), "| drill n:", await ev("document.querySelector('.mg-bot .mg-card:last-child .mg-ch small').textContent"))
        await pg.click('.mg-br.on'); print("bf cleared:", await U("bf"))
        await pg.click('rect.hit[data-i="2"]'); print("bk:", await U("bk"), "|", await ev("document.querySelector('.mg-bot .mg-card:last-child .mg-ch small').textContent"))
        await pg.hover('rect.hit[data-i="3"]'); await pg.wait_for_timeout(50); print("tip:", await ev("document.querySelector('.tk-tip').innerText.replace(/\\n/g,' / ')"))
        await pg.screenshot(path=SH+"/mg_hover.png")
        await pg.click('[data-a="pop"][data-p="per"]'); await pg.click('[data-a="pset"][data-v="lmo"]'); print("period:", await U("p"), "| hero:", await ev("document.querySelector('.mg-hero .big').textContent"))
        await pg.keyboard.press("q"); print("key q:", await U("p")); await pg.keyboard.press("m")
        await pg.click('[data-a="pin"]'); print("pin:", await T(), await ev("__mg.U().pins.length")); await pg.click('.toast-fm button'); print("undo pins:", await ev("__mg.U().pins.length"))
        await pg.click('[data-a="pin"]'); print("unpin eff:", await T(), await ev("JSON.stringify(__mg.U().pins)"))
        await ev("(()=>{__mg.U().sel='bay';__mg.render();})()"); await pg.click('[data-a="pin"]'); print("pin bay into open spot:", await T(), await ev("__mg.U().pins.indexOf('bay')"))
        await ev("(()=>{__mg.U().sel='rep';__mg.render();})()"); await pg.click('[data-a="pin"]'); print("pin when full:", await T())
        await ev("(()=>{__mg.U().sel='eff';__mg.render();})()")
        await pg.keyboard.press("t"); await pg.fill('#mg-tv','95'); await pg.keyboard.press("Enter"); await pg.wait_for_timeout(50); print("target:", await T(), "| hero tgt:", await ev("document.querySelector('.mg-hero .mg-tgt').textContent"))
        await pg.keyboard.press("j"); await pg.keyboard.press("j"); print("j j:", await U("sel"))
        await pg.fill('#mg-lq','parts'); await pg.wait_for_timeout(50); print("search parts:", await ev("[...document.querySelectorAll('.mg-it .tg-t b')].map(x=>x.textContent).join(', ')"))
        await pg.fill('#mg-lq',''); await pg.click('[data-a="lf"][data-v="off"]'); print("off target count:", await ev("document.querySelectorAll('.mg-it').length"))
        await pg.click('[data-a="lf"][data-v="all"]')
        await pg.keyboard.press("/"); await pg.keyboard.type("comeback"); await pg.keyboard.press("Enter"); print("find:", await U("sel"), await U("view"))
        await pg.keyboard.press("1"); print("view 1:", await U("view"), "| needs:", await ev("document.querySelectorAll('.mg-nd').length"))
        await pg.click('[data-a="nd"][data-id="n1"][data-i="0"]'); print("sign off:", await T(), "| head:", await ev("document.querySelector('.tg-hf.w').textContent"))
        await pg.click('.toast-fm button'); print("undo needs:", await ev("__mg.U().needs.length"))
        await pg.click('[data-a="ed"]'); await pg.click('.mg-tile[data-k="fill"] .x'); print("remove tile:", await T(), await ev("JSON.stringify(__mg.U().pins)"))
        await pg.click('[data-a="pop"][data-p="add"]'); await pg.keyboard.type("repeat"); await pg.keyboard.press("Enter"); print("add tile:", await T(), await ev("JSON.stringify(__mg.U().pins)"))
        await pg.click('[data-a="tdef"]'); print("usual 12:", await T())
        await ev("(()=>{__mg.U().view='team';__mg.U().person='FD';__mg.render();})()"); await pg.click('.mg-pg.lk'); print("locked page:", await T()); await pg.keyboard.press("1")
        await pg.click('[data-a="nd"][data-id="n4"][data-i="0"]'); print("see flow:", await U("view"), await U("flow"))
        await pg.click('.mg-fc[data-k="writer"]'); print("writer rows:", await ev("document.querySelectorAll('.mg-hr').length"))
        await pg.click('[data-a="rule"][data-k="parts"][data-v="auto"]'); print("rule:", await T())
        await pg.fill('[data-goal="parts"]','300'); await pg.dispatch_event('[data-goal="parts"]','change'); print("goal:", await T())
        await pg.keyboard.press("4"); await pg.click('.mg-pi[data-k="BO"]'); print("person BO tiles:", await ev("[...document.querySelectorAll('.mg-sc .mg-tile .l span:first-child')].map(x=>x.textContent).join(', ')"))
        await pg.click('[data-a="page"][data-v="warranty"]'); print("page:", await T())
        await pg.select_option('[data-role="BO"]','Service writer'); print("role:", await T(), "| pages:", await ev("document.querySelectorAll('.mg-pg.on').length"))
        await pg.click('.mg-pi[data-k="KT"]'); await pg.click('.mg-sc .mg-tile >> nth=0'); print("tech tile→", await U("view"), await U("sel"), await U("bf"))
        await pg.keyboard.press("5"); await pg.click('[data-a="alf"][data-v="release"]'); print("releases:", await ev("[...document.querySelectorAll('.mg-al .x')].map(x=>x.textContent.split(' ')[0]).join(',')"))
        await pg.select_option('[data-alw]','AM'); print("AM rows:", await ev("document.querySelectorAll('.mg-al').length"))
        for d in ["day","wk","lwk","mo","lmo","qt","lqt","yr"]:
            await ev(f"(()=>{{__mg.U().p='{d}';__mg.U().view='kpi';__mg.render();}})()")
            for k in ["eff","prod","sales","wip","wpn","bko","rcr","bay","dec","aw","fx","rep","wrj","wdp","late"]:
                await ev(f"(()=>{{__mg.U().sel='{k}';__mg.render();}})()")
        print("cycled all periods × KPIs")
        print(errs or "no errors"); await b.close()
asyncio.run(main())
